public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day of the week from the time bucket
    int dayOfWeek = (int) (timeBucket % 100000000);

    // Calculate the year and month from the time bucket
    int year = (int) (timeBucket / 100000000);
    int month = (int) (timeBucket % 100000000) / 10000;

    // Calculate the new day of the week based on the day step
    dayOfWeek = (dayOfWeek + dayStep) % 7;

    // Calculate the new year and month based on the day of the week
    if (dayOfWeek == 0) {
        year++;
        month = 1;
    } else if (dayOfWeek == 1) {
        month++;
    }

    // Return the new time bucket
    return (year * 100000000 + month * 10000 + dayOfWeek);
}
