public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("Desired capacity must be non-negative");
    }

    // Handle special cases
    if (desiredCapacity == 0) {
      return 1;
    } else if (desiredCapacity == 1) {
      return 2;
    }

    // Find the next prime number
    int prime = 2;
    while (prime < desiredCapacity) {
      prime++;
      if (isPrime(prime)) {
        return prime;
      }
    }

    // If we reach this point, we have found a prime number that is very close to the desired capacity
    return prime;
  }

  // Helper method to check if a number is prime
  private static boolean isPrime(int num) {
    if (num < 2) {
      return false;
    }

    for (int i = 2; i * i <= num; i++) {
      if (num % i == 0) {
        return false;
      }
    }

    return true;
  }

