public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder builder = new StringBuilder(str.length());
    boolean wasSlashEscaped = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && !wasSlashEscaped) {
            wasSlashEscaped = true;
            continue;
        }
        wasSlashEscaped = false;
        if (c == 'n') {
            builder.append('\n');
        } else if (c == 't') {
            builder.append('\t');
        } else if (c == 'b') {
            builder.append('\b');
        } else if (c == 'f') {
            builder.append('\f');
        } else if (c == 'r') {
            builder.append('\r');
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

