public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    if (node.getPrevious() == null) {
        // Node is the first element in the list
        if (node.getNext() == null) {
            // Node is the only element in the list
            head = null;
            tail = null;
        } else {
            // Node is the first element in the list, but not the only element
            head = node.getNext();
            head.setPrevious(null);
        }
    } else if (node.getNext() == null) {
        // Node is the last element in the list
        tail = node.getPrevious();
        tail.setNext(null);
    } else {
        // Node is an intermediate element in the list
        ListNodeImpl<E> previous = node.getPrevious();
        ListNodeImpl<E> next = node.getNext();
        previous.setNext(next);
        next.setPrevious(previous);
    }

    size--;
    return true;
}
