private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Check if the list is null or empty
    if (list == null || list.isEmpty()) {
        return;
    }

    // Get the head and tail of the list
    ListNode<E> head = list.getHead();
    ListNode<E> tail = list.getTail();

    // Check if the head and tail are null
    if (head == null && tail == null) {
        return;
    }

    // Remove the head and tail from the list
    list.removeListNode(head);
    list.removeListNode(tail);

    // Add the head and tail to this list
    addListNode(head);
    addListNode(tail);
}

